<?php
require dirname(__DIR__).'/bootstrap.php';requireRole('admin');$pageTitle='Subjects';$dashboardMode=true;$subjects=(new Subject())->all();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
    postOnly();$v=(new Validator())->required($_POST,'subject_name','Subject name')->length($_POST,'subject_name','Subject name',2,120);$errors=$v->errors();if(!$errors){try{$id=(new Subject())->create(['subject_name'=>trim((string)$_POST['subject_name']),'description'=>trim((string)($_POST['description']??''))?:null]);audit('subject_created','subjects',$id);Session::flash('success','Subject created.');redirectTo('admin/subjects.php');}catch(Throwable $e){$errors[]='This subject already exists or could not be saved.';}}
}
require APP_ROOT.'/components/header.php';
?>
<div class="page-heading"><div><h1>Subjects</h1><p>Maintain the subjects used in class assignments and exams.</p></div></div><?php if($errors): ?><ul class="error-list"><?php foreach($errors as $error): ?><li><?= e($error) ?></li><?php endforeach; ?></ul><?php endif; ?><div class="content-columns"><section class="panel"><div class="panel-header"><h2>Subject library</h2><span class="badge badge-blue"><?= count($subjects) ?> subjects</span></div><div class="panel-body flush"><div class="table-wrap"><table><thead><tr><th>Subject</th><th>Description</th><th></th></tr></thead><tbody><?php foreach($subjects as $subject): ?><tr><td><strong><?= e($subject['subject_name']) ?></strong></td><td><?= e($subject['description']?:'—') ?></td><td><a class="button button-outline button-small" href="<?= e(appUrl('admin/subject-edit.php?id='.(int)$subject['id'])) ?>">Edit</a></td></tr><?php endforeach; ?><?php if(!$subjects): ?><tr><td colspan="3"><div class="empty-state">No subjects have been added yet.</div></td></tr><?php endif; ?></tbody></table></div></div></section><aside class="panel"><div class="panel-header"><h2>Add subject</h2></div><div class="panel-body"><form method="post" class="form-stack"><?= CSRF::field() ?><div class="field"><label for="subject_name">Subject name</label><input id="subject_name" name="subject_name" required minlength="2" maxlength="120" value="<?= old('subject_name') ?>"></div><div class="field"><label for="description">Description</label><textarea id="description" name="description" maxlength="2000"><?= old('description') ?></textarea></div><button class="button button-primary">Save subject</button></form></div></aside></div>
<?php require APP_ROOT.'/components/footer.php'; ?>
